llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "In humans, TP-434 oral bioavailability was 28%, exceeding the 20% threshold and supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Systemic availability of ursodeoxycholic acid was 50% in healthy subjects versus IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Absolute oral bioavailability of lefamulin was 25.8% in fasted healthy subjects, supporting high bioavailability; a fed-state estimate of 19% is below threshold but less direct than absolute measurements.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All ten evidence molecules support high oral bioavailability at the F>=20% threshold; numeric absolute/systemic values range from about 21% to 99%, with only one fed-state lefamulin estimate of 19% below threshold.",
  "evidence_gaps": [
    "Molecule 3 includes a morphine controlled-release record inconsistent with the meperidine/pethidine records; it was discounted.",
    "Sodium oxybate has conflicting absolute bioavailability estimates (25-30% vs 88%), but all exceed the 20% threshold.",
    "One fed-state lefamulin estimate (19%) is below threshold, but absolute fed/fasted measurements are 21-25.8%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

